from mcp.types import Resource, Prompt, GetPromptResult, PromptMessage, TextContent

@server.list_resources()
async def list_resources() -> list[Resource]:
    return [Resource(uri="weather://cities", name="Supported Cities", mimeType="text/plain")]

@server.read_resource()
async def read_resource(uri: str) -> str:
    return "london, paris, tokyo, new-york"

@server.list_prompts()
async def list_prompts() -> list[Prompt]:
    return [Prompt(name="forecast_summary", description="Summarize a forecast in plain language")]

@server.get_prompt()
async def get_prompt(name: str, arguments: dict) -> GetPromptResult:
    return GetPromptResult(messages=[
        PromptMessage(role="user", content=TextContent(type="text", text="Summarize this forecast simply."))
    ])

import { Server } from "@modelcontextprotocol/sdk/server/index.js";

const server = new Server(
  { name: "weather-server", version: "1.0.0" },
  {
    capabilities: {
      tools: {},
      resources: { subscribe: false },
      prompts: {}
    }
  }
);

init_result = await session.initialize()

if init_result.capabilities.tools is not None:
    tools = await session.list_tools()
else:
    tools = []
    logger.info("server does not support tools, skipping")

from mcp import ClientSession

async with ClientSession(read_stream, write_stream) as session:
    init_result = await session.initialize(
        capabilities={
            "sampling": {},
            "roots": { "listChanged": True }
        }
    )

SUPPORTED_VERSIONS = ["2024-11-05", "2024-10-07"]

def negotiate_version(client_version: str) -> str:
    if client_version in SUPPORTED_VERSIONS:
        return client_version
    return SUPPORTED_VERSIONS[0]

server_capabilities = {}

async def connect_and_record(name: str, session):
    init_result = await session.initialize()
    server_capabilities[name] = init_result.capabilities

def servers_supporting_tools() -> list[str]:
    return [name for name, caps in server_capabilities.items() if caps.tools is not None]
